/* {{NAME}} - live UDP skeleton generated by new_demo.py --live udp
 *
 * Build (host smoke):  sh smoke.sh
 * Build (target):      python3 scripts/build_demo.py --demo-dir <this dir>
 * Run:                 ./{{BINARY}} --peer <host-ip> --port 5000 --control-port 5001
 *
 * The idle loop below is a placeholder. Two rules for the camera pipeline:
 *
 * 1. Video (CH2, H.264): drain it in its own thread and keep up with the
 *    encoder. Every NAL belongs in the stream; do not drop frames.
 *
 *      camera->retrieveFrame(frame, MA_PIXEL_FORMAT_H264);
 *      recamera_live::send_nal(frame.data, frame.size, frame.index, frame.count,
 *                              frame.key, recamera_live::now_ms());
 *      camera->returnFrame(frame);
 *
 * 2. Inference (CH0, RGB888): NEVER call retrieveFrame() from the slow
 *    inference loop.  ma::Camera's channel queue is FIFO with depth == channel
 *    fps and drops the NEW frame when full, so a 5 fps consumer on a 15 fps
 *    channel reads frames 3 s old.  Use live_camera.hpp instead:
 *
 *      recamera_live::FrameRelay relay;
 *      relay.start(camera, MA_PIXEL_FORMAT_RGB888);
 *      recamera_live::LatestFrame f;
 *      if (relay.wait(f)) {
 *          run_model(f.img.data, f.img.width, f.img.height);   // your code
 *          camera->returnFrame(f.img);
 *          int age_ms = f.age_ms + recamera_live::now_ms() - f.acquired_ms;
 *          recamera_live::send_meta(..., f.acquired_ms, age_ms);
 *      }
 *
 *    Set CH0 fps to the rate the consumer can actually sustain (5-8 fps for a
 *    CPU decoder, 10-15 fps for NPU inference).  A higher channel fps does not
 *    make the model faster; on the single-core SG2002 it steals CPU from it.
 *
 * The inference channel can stay at 640x640 while the H.264 channel stays at
 * 1080p; the host UI maps model-space boxes onto the 1080p frame.
 */

#include <chrono>
#include <csignal>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <thread>

#include "live_udp.h"

static volatile std::sig_atomic_t g_stop = 0;

static void on_signal(int) {
    g_stop = 1;
}

static int self_test(void) {
    const char* name = "{{NAME}}";
    if (std::strlen(name) == 0) {
        std::fprintf(stderr, "empty demo name\n");
        return 1;
    }
    std::printf("self-test ok: %s\n", name);
    return 0;
}

static void usage(const char* argv0) {
    std::printf(
        "Usage: %s [--peer IP] [--port N] [--control-port N] [--demo NAME]\n"
        "       %s --self-test\n"
        "       %s --live-self-test\n",
        argv0, argv0, argv0);
}

int main(int argc, char** argv) {
    std::setvbuf(stdout, nullptr, _IOLBF, 0);
    recamera_live::Config config;
    config.demo_name = "{{NAME}}";

    for (int i = 1; i < argc; ++i) {
        const std::string arg = argv[i];
        if (arg == "--self-test") {
            return self_test();
        }
        if (arg == "--live-self-test") {
            return recamera_live::selftest() ? 0 : 1;
        }
        if (arg == "--peer" && i + 1 < argc) {
            config.host = argv[++i];
        } else if (arg == "--port" && i + 1 < argc) {
            config.video_port = static_cast<uint16_t>(std::atoi(argv[++i]));
        } else if (arg == "--control-port" && i + 1 < argc) {
            config.control_port = static_cast<uint16_t>(std::atoi(argv[++i]));
        } else if (arg == "--demo" && i + 1 < argc) {
            config.demo_name = argv[++i];
        } else if (arg == "-h" || arg == "--help") {
            usage(argv[0]);
            return 0;
        } else {
            std::fprintf(stderr, "unknown argument: %s\n", arg.c_str());
            usage(argv[0]);
            return 2;
        }
    }

    std::signal(SIGINT, on_signal);
    std::signal(SIGTERM, on_signal);

    if (config.host.empty()) {
        std::fprintf(stderr, "live: --peer <host-ip> is required "
                             "(LAN address of the computer running serve_demo.py)\n");
        return 2;
    }

    if (!recamera_live::start(config)) {
        std::fprintf(stderr, "live: start failed (peer=%s:%u control=%u)\n",
                     config.host.c_str(), config.video_port, config.control_port);
        return 1;
    }
    std::printf("live: started peer=%s:%u control=%u\n",
                config.host.c_str(), config.video_port, config.control_port);
    recamera_live::send_log("info", "demo %s online; waiting for camera pipeline",
                            config.demo_name.c_str());

    unsigned last_version = recamera_live::params().version.load();
    while (!g_stop) {
        if (recamera_live::force_keyframe_requested()) {
            std::printf("live: key frame requested\n");
            /* Real demos force an IDR here; the host will also recover on the
             * next natural key frame if the encoder cannot be nudged. */
        }
        const unsigned version = recamera_live::params().version.load();
        if (version != last_version) {
            last_version = version;
            std::printf("live: params confidence=%.3f nms=%.3f max_det=%d\n",
                        recamera_live::params().confidence.load(),
                        recamera_live::params().nms.load(),
                        recamera_live::params().max_det.load());
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(200));
    }

    recamera_live::stop();
    std::printf("live: stopped\n");
    return 0;
}